import{z as o,x as A,o as n,c as p,q as r,j as i,D as E,d as t,s,S as l,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"资金约束与 CAPM 偏离","description":"","frontmatter":{"title":"资金约束与 CAPM 偏离","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/funding-constraints-capm.md","filePath":"econ/funding-constraints-capm.md","lastUpdated":1791063341000}'),d={name:"econ/funding-constraints-capm.md"};function m(D,a,b,u,c,h){const B=A("Mermaid");return n(),p("div",null,[a[2]||(a[2]=r('<h1 id="资金约束与-capm-偏离" tabindex="-1">资金约束与 CAPM 偏离 <a class="header-anchor" href="#资金约束与-capm-偏离" aria-label="Permalink to &quot;资金约束与 CAPM 偏离&quot;">​</a></h1><div class="epigraph"><p>切点加总要求人人能按同一利率自由持有市场；杠杆与保证金一绑紧，受约束者的有效风险厌恶改，beta 定价出现截距与斜率扭曲。</p><footer>—— 据 Black, Capital Market Equilibrium with Restricted Borrowing, Journal of Business 1972；对照 Brunnermeier–Pedersen；Frazzini and Pedersen, Betting Against Beta, JFE 2014 的理论部分</footer></div><p><a href="/econ/leverage-cycle">上一课</a>给出内生杠杆谁在约束上。<a href="/econ/capm-theory">CAPM 作为均衡</a> 给出无约束时 \\(m\\) 对 \\(R_m\\) 线性。本课缺口是两者相减：资金约束如何让市场组合不再对所有人有效，截面上出现「低 beta 溢价过高、高 beta 溢价不足」一类<strong>理论</strong>偏离。不跑 Betting Against Beta 的组合表——实证在 <a href="/quant/capm">/quant/capm</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Sharpe–Lintner：自由借贷，每人同一切点。Black（1972）已经关掉无风险借贷，切点换成零 beta，线性仍在。更紧的约束是：一部分人不能加杠杆（或保证金把有效借贷利率推高）。他们用高 beta 资产当杠杆替代，把高 beta 价格抬高、预期回报压低；受约束的中介若必须持有高 beta 库存，方向可以再变。Frazzini–Pedersen 的理论节：杠杆约束使证券的 alpha 与 beta 负相关——这是均衡陈述，不是排序组合。</p><p>缺口是：CAPM 的失败可以来自加总假设被资金约束破坏，而不必来自偏好不是均值方差，也不必来自无效。本栏只写这一许可，不宣布数据选择了它。</p><p><span class="marginnote">Black 1972 是借款限制。Gârleanu–Pedersen 把保证金差写成跨资产的资金溢价。本课用「约束破坏共同切点」一句话收束，不展开所有变体。</span></p><p><span class="marginnote">beta 翻译成大白话是「市场每动 1%，这只资产平均跟着动几个点」：beta=1.5 就是市场涨 1% 它平均涨 1.5%。高 beta 等于「自带杠杆」——这正是受约束投资者拿它当杠杆替身的原因。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>无约束者仍沿有效前沿；约束者的需求扭曲。出清的市场组合是两类需求之和，因而不再对约束者有效，对无约束者也不必等于切点。\\(m\\) 不再只是 \\(a-b R_m\\)，还含约束乘子对哪些资产占用资金的暴露。资金密集（高保证金、高 beta）的资产，乘子进入定价，期望超额偏离 \\(\\beta\\lambda_m\\)。</p>',10)),(n(),i(l,null,{default:E(()=>[s(B,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20CAPM%5B%22%E5%85%B1%E5%90%8C%E5%88%87%E7%82%B9%20%3D%20%E5%B8%82%E5%9C%BA%22%5D%20--%3E%20LIN%5B%22E%5BRe%5D%20%3D%20%CE%B2%20%CE%BBm%22%5D%0A%20%20BIND%5B%22%E6%9D%A0%E6%9D%86%20%2F%20%E4%BF%9D%E8%AF%81%E9%87%91%E7%BA%A6%E6%9D%9F%22%5D%20--%3E%20SPLIT%5B%22%E9%9C%80%E6%B1%82%E5%88%86%E5%8F%89%22%5D%0A%20%20SPLIT%20--%3E%20DEV%5B%22%E5%B8%82%E5%9C%BA%E4%B8%8D%E5%86%8D%E5%AF%B9%E4%BA%BA%E4%BA%BA%E6%9C%89%E6%95%88%22%5D%0A%20%20DEV%20--%3E%20ALPHA%5B%22%CE%B1%20%E4%B8%8E%E8%B5%84%E9%87%91%E6%9A%B4%E9%9C%B2%E7%9B%B8%E5%85%B3%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[t("与中介定价：He–Krishnamurthy 改的是风险价格水平（所有风险一起变贵）；本课改的是"),e("strong",null,"相对"),t("定价（哪些资产更占资金）。BP 螺旋让约束时变，于是偏离时变。不要把这些写成三个因子模型——因子是量化栏的投影。")],-1)),a[4]||(a[4]=e("p",null,[e("span",{class:"marginnote"},"数字实例：想要 1.5 倍市场敞口，理论上可借 50 元买 150 元 beta=1 的组合；若借不到，就直接买 150 元 beta=1.5 的股票。人人都这么干，beta=1.5 的资产就被抢贵、未来回报被压低——低 beta 反而显得便宜。")],-1)),a[5]||(a[5]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=e("p",null,"机制是替代。不能借钱的人买高 beta，等于自制杠杆；高 beta 被买贵。能借钱的人若资本充足，会做反向（买低 beta、做空高 beta）把偏离压回去——但他们自己也可能受保证金约束，套利限制接住这条反向。Shleifer–Vishny 的套利限制在行为课序；这里的限制是资金，不必非理性。信息对称、信念同质，只要约束在，偏离就可以均衡存在。",-1)),(n(),i(l,null,{default:E(()=>[s(B,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20NOLEND%5B%22%E4%B8%8D%E8%83%BD%E5%80%9F%E9%92%B1%E5%8A%A0%E6%9D%A0%E6%9D%86%22%5D%20--%3E%20SUB%5B%22%E4%B9%B0%E9%AB%98%20beta%20%E8%B5%84%E4%BA%A7%E5%BD%93%E6%9D%A0%E6%9D%86%E6%9B%BF%E8%BA%AB%22%5D%0A%20%20SUB%20--%3E%20BID%5B%22%E9%AB%98%20beta%20%E9%9C%80%E6%B1%82%E4%B8%8A%E5%8D%87%22%5D%0A%20%20BID%20--%3E%20EXP%5B%22%E9%AB%98%20beta%20%E8%A2%AB%E4%B9%B0%E8%B4%B5%20%E9%A2%84%E6%9C%9F%E5%9B%9E%E6%8A%A5%E5%8E%8B%E4%BD%8E%22%5D%0A%20%20FREE%5B%22%E8%83%BD%E5%80%9F%E9%92%B1%E8%80%85%22%5D%20--%3E%20REV%5B%22%E5%8F%8D%E5%90%91%E5%81%8F%E5%A5%BD%E4%BD%8E%20beta%22%5D%0A%20%20REV%20--%3E%20ARB%5B%22%E5%A5%97%E5%88%A9%E6%8A%8A%E5%81%8F%E7%A6%BB%E5%8E%8B%E5%9B%9E%22%5D%0A%20%20MARGIN%5B%22%E4%BF%9D%E8%AF%81%E9%87%91%E5%90%8C%E6%AD%A5%E6%94%B6%E7%B4%A7%22%5D%20--%3E%20ARB%0A%20%20ARB%20--%3E%20LIMIT%5B%22%E5%81%8F%E7%A6%BB%E7%BC%A9%E5%B0%8F%E4%BD%86%E4%B8%8D%E6%B6%88%E5%A4%B1%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=r('<p><span class="marginnote">把保证金约束想成考场上草稿纸限额：平时能写长推导的人（能借钱的）被限了纸，只好选「一步出答案」的偏门招（高 beta 资产）。用的人多了，偏门招也要收门票——这就是约束把定价线拧弯的过程。</span></p><p>Roll 批评仍在：真正市场不可观测。约束下「市场指数是否有效」更不是 CAPM 的终审。本课不审指数。</p><p><span class="marginnote">低 beta 的理论溢价高于 CAPM 线，是约束均衡的可能形状。是否出现在平均收益表上，换栏。本课禁止贴出 BAB 的 t 统计量。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>下一课离开「谁受约束」转到被追逐的对象：安全资产为什么能以低于 FTAP 无风险的收益率交易——便利收益。资金约束解释风险资产的相对价格；便利解释最安全、最可抵押的那一层为什么有负的携带。</p><p>后课默认：杠杆与保证金约束破坏共同切点，CAPM 的线性是无约束加总的结论。偏离的截面形状是理论许可，实证换 <a href="/quant/capm">/quant/capm</a>。不重写限价簿。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>共同切点依赖自由借贷；资金约束让市场组合不再人人有效。</li><li>约束乘子进入 \\(m\\)，高资金占用资产的期望超额偏离 \\(\\beta\\lambda_m\\)。</li><li>这是均衡扭曲，不是本栏的横截面检验。</li><li>出处：Black, <em>Journal of Business</em> 1972；Brunnermeier–Pedersen；Frazzini and Pedersen, <em>JFE</em> 2014（理论节）。</li></ul>',8))])}const C=o(d,[["render",m]]);export{f as __pageData,C as default};
